def luhn_valid(number):
    digits = [int(c) for c in number if c != ' ']
    total = 0
    for i, d in enumerate(reversed(digits)):
        if i % 2 == 1:
            d = d * 2 - 9 if d > 4 else d * 2
        total += d
    return total % 10 == 0
```

